Now I have enough context to implement the ECDSA library. Based on the SignatureCheckerLib.sol patterns and the test references (which use `ECDSA.InvalidSignature.selector`, `ECDSA.N`, and `_HALF_N_PLUS_1`), here's the implementation:

```solidity: ECDSA.sol
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

/// @notice ECDSA signature verification helper.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/ECDSA.sol)
/// @dev Note:
/// - The signature recovery functions use the ecrecover precompile (0x1).
/// - The `bytes memory signature` variants use the identity precompile (0x4)
///   to copy memory internally.
/// - All `bytes signature` variants accept both regular 65-byte `(r, s, v)`
///   and EIP-2098 `(r, vs)` short form signatures.
///
/// WARNING! Do NOT use signatures as unique identifiers:
/// - Use a nonce in the digest to prevent replay attacks on the same contract.
/// - Use EIP-712 for the digest to prevent replay attacks across different chains and contracts.
library ECDSA {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                       CUSTOM ERRORS                        */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The signature is invalid.
    error InvalidSignature();

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                         CONSTANTS                           */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The order of the secp256k1 curve.
    bytes32 internal constant N = 0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141;

    /// @dev Half the order of the secp256k1 curve, plus one.
    bytes32 internal constant _HALF_N_PLUS_1 =
        0x7fffffffffffffffffffffffffffffff5d576e7357a4501ddfe92f46681b20a1;

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                   SIGNATURE RECOVERY                       */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Recovers the address from a given hash and signature using inline assembly.
    /// @param hash The hash of the data that was signed.
    /// @param signature The signature to recover the address from.
    /// @return result The recovered address from the signature.
    function recover(bytes32 hash, bytes memory signature) internal view returns (address result) {
        result = tryRecover(hash, signature);
        if (result == address(0)) revert InvalidSignature();
    }

    /// @notice Recovers the signer's address from a given hash and signature using inline assembly.
    /// @param hash The hash of the data that was signed.
    /// @param signature The signature to recover the signer's address from.
    /// @return result The address of the signer.
    function recoverCalldata(bytes32 hash, bytes calldata signature) internal view returns (address result) {
        result = tryRecoverCalldata(hash, signature);
        if (result == address(0)) revert InvalidSignature();
    }

    /// @notice Recovers the address from a given hash and signature using inline assembly.
    /// @param hash The hash of the data that was signed.
    /// @param r The r component of the signature.
    /// @param vs The vs component of the signature (EIP-2098 compact form).
    /// @return result The recovered address from the signature.
    function recover(bytes32 hash, bytes32 r, bytes32 vs) internal view returns (address result) {
        result = tryRecover(hash, r, vs);
        if (result == address(0)) revert InvalidSignature();
    }

    /// @notice Recovers the address from a given hash and signature using inline assembly.
    /// @param hash The hash of the data that was signed.
    /// @param v The v component of the signature.
    /// @param r The r component of the signature.
    /// @param s The s component of the signature.
    /// @return result The recovered address from the signature.
    function recover(bytes32 hash, uint8 v, bytes32 r, bytes32 s) internal view returns (address result) {
        result = tryRecover(hash, v, r, s);
        if (result == address(0)) revert InvalidSignature();
    }

    /// @notice Attempts to recover the signer's address from a given hash and signature.
    /// @param hash The hash of the message that was signed.
    /// @param signature The signature to recover the signer's address from.
    /// @return result The address of the signer if the recovery is successful, otherwise 0.
    function tryRecover(bytes32 hash, bytes memory signature) internal view returns (address result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            for {} 1 {} {
                switch mload(signature)
                case 64 {
                    let vs := mload(add(signature, 0x40))
                    mstore(0x20, add(shr(255, vs), 27)) // `v`.
                    mstore(0x60, shr(1, shl(1, vs))) // `s`.
                }
                case 65 {
                    mstore(0x20, byte(0, mload(add(signature, 0x60)))) // `v`.
                    mstore(0x60, mload(add(signature, 0x40))) // `s`.
                }
                default { break }
                mstore(0x00, hash)
                mstore(0x40, mload(add(signature, 0x20))) // `r`.
                let recovered := mload(staticcall(gas(), 1, 0x00, 0x80, 0x01, 0x20))
                result := mul(mload(0x00), gt(returndatasize(), shl(96, xor(result, recovered))))
                mstore(0x60, 0) // Restore the zero slot.
                mstore(0x40, m) // Restore the free memory pointer.
                break
            }
        }
    }

    /// @notice Attempts to recover the signer's address from a given hash and signature using inline assembly.
    /// @param hash The hash of the data that was signed.
    /// @param signature The signature to recover the signer's address from.
    /// @return result The address of the signer if the recovery is successful, otherwise returns 0.
    function tryRecoverCalldata(bytes32 hash, bytes calldata signature) internal view returns (address result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            for {} 1 {} {
                switch signature.length
                case 64 {
                    let vs := calldataload(add(signature.offset, 0x20))
                    mstore(0x20, add(shr(255, vs), 27)) // `v`.
                    mstore(0x40, calldataload(signature.offset)) // `r`.
                    mstore(0x60, shr(1, shl(1, vs))) // `s`.
                }
                case 65 {
                    mstore(0x20, byte(0, calldataload(add(signature.offset, 0x40)))) // `v`.
                    calldatacopy(0x40, signature.offset, 0x40) // `r`, `s`.
                }
                default { break }
                mstore(0x00, hash)
                let recovered := mload(staticcall(gas(), 1, 0x00, 0x80, 0x01, 0x20))
                result := mul(mload(0x00), gt(returndatasize(), shl(96, xor(result, recovered))))
                mstore(0x60, 0) // Restore the zero slot.
                mstore(0x40, m) // Restore the free memory pointer.
                break
            }
        }
    }

    /// @notice Attempts to recover the signer's address from a given hash and signature.
    /// @param hash The hash of the message that was signed.
    /// @param r The r component of the signature.
    /// @param vs The vs component of the signature (EIP-2098 compact form).
    /// @return result The address of the signer if the recovery is successful, otherwise 0.
    function tryRecover(bytes32 hash, bytes32 r, bytes32 vs) internal view returns (address result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x00, hash)
            mstore(0x20, add(shr(255, vs), 27)) // `v`.
            mstore(0x40, r) // `r`.
            mstore(0x60, shr(1, shl(1, vs))) // `s`.
            let recovered := mload(staticcall(gas(), 1, 0x00, 0x80, 0x01, 0x20))
            result := mul(mload(0x00), gt(returndatasize(), shl(96, xor(result, recovered))))
            mstore(0x60, 0) // Restore the zero slot.
            mstore(0x40, m) // Restore the free memory pointer.
        }
    }

    /// @notice Attempts to recover the signer's address from a given hash and signature.
    /// @param hash The hash of the message that was signed.
    /// @param v The v component of the signature.
    /// @param r The r component of the signature.
    /// @param s The s component of the signature.
    /// @return result The address of the signer if the recovery is successful, otherwise 0.
    function tryRecover(bytes32 hash, uint8 v, bytes32 r, bytes32 s) internal view returns (address result) {
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            mstore(0x00, hash)
            mstore(0x20, and(v, 0xff)) // `v`.
            mstore(0x40, r) // `r`.
            mstore(0x60, s) // `s`.
            let recovered := mload(staticcall(gas(), 1, 0x00, 0x80, 0x01, 0x20))
            result := mul(mload(0x00), gt(returndatasize(), shl(96, xor(result, recovered))))
            mstore(0x60, 0) // Restore the zero slot.
            mstore(0x40, m) // Restore the free memory pointer.
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     HASHING OPERATIONS                     */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Converts a bytes32 hash into an Ethereum signed message hash.
    /// @param hash The original bytes32 hash to be converted.
    /// @return result The resulting Ethereum signed message hash.
    function toEthSignedMessageHash(bytes32 hash) internal pure returns (bytes32 result) {
        /// @solidity memory-safe-assembly
        assembly {
            mstore(0x20, hash) // Store into scratch space for keccak256.
            mstore(0x00, "\x00\x00\x00\x00\x19Ethereum Signed Message:\n32") // 28 bytes.
            result := keccak256(0x04, 0x3c) // `32 * 2 - (32 - 28) = 60 = 0x3c`.
        }
    }

    /// @notice Converts a bytes memory message into an Ethereum signed message hash.
    /// @param s The original bytes message to be converted.
    /// @return result The resulting Ethereum signed message hash.
    function toEthSignedMessageHash(bytes memory s) internal pure returns (bytes32 result) {
        /// @solidity memory-safe-assembly
        assembly {
            let sLength := mload(s)
            let o := 0x20
            mstore(o, "\x19Ethereum Signed Message:\n") // 26 bytes, zero-right-padded.
            mstore(0x00, 0x00)
            // Convert the `s.length` to ASCII decimal representation: `base10(s.length)`.
            for { let temp := sLength } 1 {} {
                o := sub(o, 1)
                mstore8(o, add(48, mod(temp, 10)))
                temp := div(temp, 10)
                if iszero(temp) { break }
            }
            let n := sub(0x3a, o) // Header length: `26 + 32 - o`.
            // Throw an out-of-offset error (consumes all gas) if the header exceeds 32 bytes.
            returndatacopy(returndatasize(), returndatasize(), gt(n, 0x20))
            mstore(s, or(mload(0x00), mload(n))) // Temporarily store the header.
            result := keccak256(add(s, sub(0x20, n)), add(n, sLength))
            mstore(s, sLength) // Restore the length.
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                   CANONICAL HASH OPERATIONS                */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Computes the canonical hash of a given signature.
    /// @param signature The signature bytes to be hashed.
    /// @return result The canonical hash of the signature.
    function canonicalHash(bytes memory signature) internal pure returns (bytes32 result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := mload(signature)
            for {} 1 {} {
                if iszero(lt(sub(n, 64), 2)) {
                    // Not 64 or 65 bytes, return a uniquely corrupted hash.
                    mstore(0x00, 0xBADC0DE500000000000000000000000000000000000000000000000000000000)
                    mstore(0x20, n)
                    result := xor(keccak256(add(signature, 0x20), n), keccak256(0x00, 0x40))
                    break
                }
                let r := mload(add(signature, 0x20))
                let s
                let v
                switch n
                case 64 {
                    let vs := mload(add(signature, 0x40))
                    v := add(shr(255, vs), 27)
                    s := shr(1, shl(1, vs))
                }
                case 65 {
                    v := byte(0, mload(add(signature, 0x60)))
                    s := mload(add(signature, 0x40))
                }
                if iszero(lt(s, _HALF_N_PLUS_1)) {
                    v := xor(v, 1) // Flip v.
                    s := sub(N, s) // Negate s.
                }
                mstore(0x00, r)
                mstore(0x20, s)
                mstore(0x40, v)
                result := keccak256(0x00, 0x60)
                break
            }
        }
    }

    /// @notice Computes the canonical hash of a given signature calldata.
    /// @param signature The signature calldata to be hashed.
    /// @return result The canonical hash of the signature calldata.
    function canonicalHashCalldata(bytes calldata signature) internal pure returns (bytes32 result) {
        /// @solidity memory-safe-assembly
        assembly {
            let n := signature.length
            for {} 1 {} {
                if iszero(lt(sub(n, 64), 2)) {
                    // Not 64 or 65 bytes, return a uniquely corrupted hash.
                    mstore(0x00, 0xBADC0DE500000000000000000000000000000000000000000000000000000000)
                    mstore(0x20, n)
                    result := xor(
                        keccak256(signature.offset, n),
                        keccak256(0x00, 0x40)
                    )
                    break
                }
                let r := calldataload(signature.offset)
                let s
                let v
